namespace AutosurBuscador {
using System;using System.Collections.Generic;using System.Diagnostics;using System.Globalization;using System.IO;using System.IO.Compression;using System.Linq;using System.Net;using System.Security.Cryptography;using System.Text;using System.Threading.Tasks;using System.Web.Script.Serialization;using System.Windows.Forms;
public static class UpdateManager {
 public const string AppVersion="1.3.9";
 public const string Repository="juancarlosamarante94-alt/Buscador-Autosur-Objetivos";
 public const string PackageName="Buscador_Autosur_Objetivos_Actualizacion.zip";
 public const string PackageFolder="Buscador_VIN_Instalable";
 public const string AppName="Buscador Autosur Objetivos";
 static string Api {get{return "https://api.github.com/repos/"+Repository;}}
 public static void RemoveLegacyAccess(){try{string p=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),AppName,"datos","github-access.bin");if(File.Exists(p))File.Delete(p);}catch(IOException){}catch(UnauthorizedAccessException){}}
 class Client:WebClient {protected override WebRequest GetWebRequest(Uri address){var r=base.GetWebRequest(address);r.Timeout=30000;return r;}}
 static Client Web(bool asset){ServicePointManager.SecurityProtocol=(SecurityProtocolType)3072;var w=new Client();w.Encoding=Encoding.UTF8;w.Headers[HttpRequestHeader.UserAgent]=AppName.Replace(' ','-')+"/"+AppVersion;w.Headers[HttpRequestHeader.Accept]=asset?"application/octet-stream":"application/vnd.github+json";if(!asset)w.Headers["X-GitHub-Api-Version"]="2022-11-28";return w;}
 public static Dictionary<string,object> PublishedRelease(){using(var w=Web(false))return new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(w.DownloadString(Api+"/releases/latest"));}
 public static Dictionary<string,object> FindPackage(Dictionary<string,object> release){object value;if(release==null||!release.TryGetValue("assets",out value)||value is string)throw new Exception("La versión publicada no contiene una lista de archivos válida.");var entries=value as System.Collections.IEnumerable;if(entries==null)throw new Exception("La versión publicada no contiene una lista de archivos válida.");foreach(object entry in entries){var asset=entry as Dictionary<string,object>;object name;if(asset!=null&&asset.TryGetValue("name",out name)&&String.Equals(Convert.ToString(name),PackageName,StringComparison.Ordinal))return asset;}throw new Exception("La versión publicada todavía no tiene el paquete instalable esperado.");}
 static string Q(string s){return "'"+s.Replace("'","''")+"'";}
 public static void ValidatePackage(string path){using(var z=ZipFile.OpenRead(path)){if(z.GetEntry(PackageFolder+"/Instalar.ps1")==null)throw new Exception("El paquete no corresponde a esta aplicación.");foreach(var e in z.Entries){string n=e.FullName.Replace('\\','/');if(n.StartsWith("/")||n.Split('/').Any(x=>x==".."||x.Contains(':')))throw new Exception("El paquete contiene una ruta inválida.");if(!n.StartsWith(PackageFolder+"/",StringComparison.Ordinal))throw new Exception("El paquete contiene archivos fuera de la aplicación.");if(n.EndsWith(".dat",StringComparison.OrdinalIgnoreCase))throw new Exception("Las actualizaciones no deben incluir bases DAT.");}}}
 public static void DownloadPackage(Dictionary<string,object> asset,string zip){object name,address;if(!asset.TryGetValue("name",out name)||Convert.ToString(name)!=PackageName||!asset.TryGetValue("browser_download_url",out address))throw new Exception("No se encontró el paquete de actualización.");Uri url;if(!Uri.TryCreate(Convert.ToString(address),UriKind.Absolute,out url)||url.Scheme!="https"||!String.Equals(url.Host,"github.com",StringComparison.OrdinalIgnoreCase)||!url.AbsolutePath.StartsWith("/"+Repository+"/releases/download/",StringComparison.Ordinal))throw new Exception("La descarga no corresponde al repositorio de Autosur.");
 using(var w=Web(true))w.DownloadFile(url,zip);object digest;if(asset.TryGetValue("digest",out digest)&&digest!=null&&digest.ToString().StartsWith("sha256:",StringComparison.OrdinalIgnoreCase)){using(var stream=File.OpenRead(zip))using(var hash=SHA256.Create()){string actual=BitConverter.ToString(hash.ComputeHash(stream)).Replace("-","").ToLowerInvariant();if(actual!=digest.ToString().Substring(7).ToLowerInvariant())throw new Exception("La verificación de integridad del paquete falló.");}}ValidatePackage(zip);}
 public static async void Check(Form owner,Button button){button.Enabled=false;try{RemoveLegacyAccess();button.Text="Buscando...";var release=await Task.Run(()=>PublishedRelease());
 Version latest,current;if(!Version.TryParse(release["tag_name"].ToString().TrimStart('v','V'),out latest)||!Version.TryParse(AppVersion,out current))throw new Exception("La versión publicada no tiene un formato válido.");if(latest<=current){MessageBox.Show(owner,"Ya tenés la última versión ("+AppVersion+").","Actualizaciones");return;}
 var asset=FindPackage(release);
 if(MessageBox.Show(owner,"Nueva versión "+latest+".\n¿Descargarla e instalarla ahora? Se conservarán tus bases, historial y objetivos.","Actualización disponible",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;
 string temp=Path.Combine(Path.GetTempPath(),AppName.Replace(' ','_')+"_"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);string zip=Path.Combine(temp,"actualizacion.zip");button.Text="Descargando...";await Task.Run(()=>DownloadPackage(asset,zip));
 string extract=Path.Combine(temp,"contenido"),script=Path.Combine(temp,"actualizar.ps1"),installer=Path.Combine(extract,PackageFolder,"Instalar.ps1");int pid=Process.GetCurrentProcess().Id;
 File.WriteAllText(script,"$ErrorActionPreference='Stop'\r\ntry {\r\nWait-Process -Id "+pid+" -Timeout 60 -ErrorAction SilentlyContinue\r\nSet-Location "+Q(temp)+"\r\nExpand-Archive -LiteralPath "+Q(zip)+" -DestinationPath "+Q(extract)+" -Force\r\n& "+Q(installer)+"\r\n} catch { Add-Type -AssemblyName System.Windows.Forms; [System.Windows.Forms.MessageBox]::Show($_.Exception.Message,'No se pudo actualizar') | Out-Null }\r\n",Encoding.UTF8);
 Process.Start(new ProcessStartInfo{FileName="powershell.exe",Arguments="-NoProfile -ExecutionPolicy Bypass -File \""+script+"\"",WorkingDirectory=temp,UseShellExecute=true});Application.Exit();
 }catch(WebException){MessageBox.Show(owner,"No se pudo consultar o descargar la actualización. Revisá Internet e intentá nuevamente más tarde.","Actualizaciones",MessageBoxButtons.OK,MessageBoxIcon.Warning);}catch(Exception ex){MessageBox.Show(owner,ex.Message,"Actualizaciones",MessageBoxButtons.OK,MessageBoxIcon.Error);}finally{if(!button.IsDisposed){button.Enabled=true;button.Text="Buscar actualizaciones";}}}
}
}

